// EventRegistry returns every registered descriptor in stable official-name order.
// Returned slices are independent of the immutable decoder registry.
func EventRegistry() []EventDescriptor {
	result := make([]EventDescriptor, 0, len(eventNames))
	for _, name := range eventNames {
		result = append(result, cloneEventDescriptor(eventRegistry[name].descriptor))
	}
	return result
}

