// LookupEvent recognizes only official module-visible names; no legacy aliases.
func LookupEvent(name string) (EventDescriptor, bool) {
	entry, ok := eventRegistry[name]
	if !ok {
		return EventDescriptor{}, false
	}
	return cloneEventDescriptor(entry.descriptor), true
}

func cloneEventDescriptor(source EventDescriptor) EventDescriptor {
	result := source
	result.IntentAlternatives = make([][]string, len(source.IntentAlternatives))
	for i, intents := range source.IntentAlternatives {
		result.IntentAlternatives[i] = append([]string(nil), intents...)
	}
	result.ConditionalIntents = append([]string(nil), source.ConditionalIntents...)
	return result
}

// DecodeEvent validates the backend, major, official event name and exact type URL
// before unmarshalling into its registered concrete generated DTO. Callers use a
// type switch on the result, never Any/raw dispatch. It does not infer field
// presence from zero-filled SDK values or manufacture before snapshots.
func DecodeEvent(envelope *corev2.EventEnvelope) (proto.Message, error) {
	return strictDecodeEvent(envelope)
}

func strictDecodeEvent(envelope *corev2.EventEnvelope) (proto.Message, error) {
	if envelope == nil {
		return nil, fmt.Errorf("discord event: missing envelope")
	}
	if envelope.BackendId != "discord" || envelope.BackendMajor != 2 {
		return nil, fmt.Errorf("discord event: unsupported backend or major")
	}
	entry, ok := eventRegistry[envelope.EventType]
	if !ok {
		return nil, fmt.Errorf("discord event: unregistered event type")
	}
	if envelope.Payload == nil || envelope.Payload.TypeUrl != entry.descriptor.TypeURL {
		return nil, fmt.Errorf("discord event: payload type URL mismatch")
	}
	value := entry.newMessage()
	if err := proto.Unmarshal(envelope.Payload.Value, value); err != nil {
		return nil, fmt.Errorf("discord event: malformed typed payload: %w", err)
	}
	return value, nil
}
